"use client"

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import {
  Button as AriaButton,
  composeRenderProps,
  type ButtonProps as AriaButtonProps,
} from "react-aria-components"

import { cn } from "@/lib/utils"

const buttonVariants = cva(
  [
    "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium transition-colors",
    /* Disabled */
    "data-disabled:pointer-events-none data-disabled:opacity-50 ",
    /* Focus Visible */
    "data-focus-visible:outline-hidden data-focus-visible:ring-1 data-focus-visible:ring-ring ",
    /* Resets */
    "focus-visible:outline-hidden",
  ],
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground shadow-sm data-hovered:bg-primary/90",
        destructive:
          "bg-destructive text-destructive-foreground shadow-xs data-hovered:bg-destructive/90",
        outline:
          "border border-input bg-background shadow-xs  data-hovered:bg-accent data-hovered:text-accent-foreground",
        secondary:
          "bg-secondary text-secondary-foreground shadow-xs data-hovered:bg-secondary/80",
        ghost: "data-hovered:bg-accent data-hovered:text-accent-foreground",
        link: "text-primary underline-offset-4 data-hovered:underline",
      },
      size: {
        default: "h-9 px-4 py-2",
        sm: "h-8 rounded-md px-3 text-xs",
        lg: "h-10 rounded-md px-8",
        icon: "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

interface ButtonProps
  extends AriaButtonProps, VariantProps<typeof buttonVariants> {}

const Button = ({ className, variant, size, ...props }: ButtonProps) => {
  return (
    <AriaButton
      className={composeRenderProps(className, (className) =>
        cn(
          buttonVariants({
            variant,
            size,
            className,
          })
        )
      )}
      {...props}
    />
  )
}

export { Button, buttonVariants }
export type { ButtonProps }

